def property_for(codepoint: int, ranges, default: str) -> str:
    """Return property for codepoint from sorted inclusive ranges."""
    lo, hi = 0, len(ranges)
    while lo < hi:
        mid = (lo + hi) // 2
        start, end, value = ranges[mid]
        if codepoint < start:
            hi = mid
        elif codepoint > end:
            lo = mid + 1
        else:
            return value
    return default
